const DE = {
 "id": "pro192-cs6-tiem-phu-thuoc",
 "title": "An overdue report that read the clock by itself: inject Clock, repository and sink",
 "src": "src",
 "extra": [],
 "main": "Main",
 "javaMin": 17,
 "timeoutMs": 10000,
