 "title": "Importing devices from CSV: one exception type with a code, a line number and the cause",
 "src": "src",
 "extra": [],
 "main": "Main",
 "javaMin": 17,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [],
 "cases": [
  {
   "name": "six rows, four of them bad",
   "input": "D01,Oscilloscope,3,9500000\nD02,Raspberry Pi,10,1800000\nD03,Multimeter,1O,350000\nd01,Oscilloscope copy,1,9500000\nD04,Breadboard,20\nD05,Laptop,2,0\n",
   "expected": "line 3: IMP_02 bad number \"1O\" (cause: NumberFormatException)\nline 4: IMP_03 duplicate code d01\nline 5: IMP_01 missing field (3 fields)\nline 6: IMP_04 non-positive value\nimported 2: [Device[code=D01, name=Oscilloscope, quantity=3, price=9500000], Device[code=D02, name=Raspberry Pi, quantity=10, price=1800000]]\n"
  },
